use std::fs;
use std::path::{Path, PathBuf};
use std::io::{self, Write};
use std::collections::HashMap;

const MAX_PATH_DEPTH: usize = 8;
const UPLOAD_ROOT: &str = "/var/app/uploads";

/// Represents a user session with upload capabilities
pub struct UploadSession {
    user_id: String,
    base_dir: PathBuf,
    quota_bytes: u64,
    used_bytes: u64,
}

/// Counts the number of path components (segments between separators)
fn count_path_segments(path: &str) -> usize {
    path.split('/').filter(|s| !s.is_empty()).count()
}

/// Validates that a normalized path doesn't escape the sandbox
/// Returns the number of "up" traversals that remain after cancellation
fn net_traversal_depth(path: &str) -> i32 {
    let mut depth: i32 = 0;
    for component in path.split('/') {
        match component {
            "" | "." => continue,
            ".." => depth -= 1,
            _ => depth += 1,
        }
    }
    depth
}

/// Sanitizes a filename component - removes null bytes and control chars
fn sanitize_component(component: &str) -> String {
    component.chars()
        .filter(|c| !c.is_control() && *c != '\0')
        .collect()
}

/// Core path validation: ensures the resolved path stays within bounds
/// Uses a two-phase approach:
///   Phase 1: Check net traversal depth (must be >= 0)
///   Phase 2: Check each prefix doesn't go negative beyond threshold
fn validate_path_safety(relative_path: &str, max_depth: usize) -> Result<PathBuf, String> {
    // Phase 1: Quick net depth check
    let net_depth = net_traversal_depth(relative_path);
    if net_depth < 0 {
        return Err("Path escapes upload directory".to_string());
    }

    // Phase 2: Walk the path and track minimum depth reached
    let mut current_depth: i32 = 0;
    let mut min_depth: i32 = 0;
    let mut cleaned_components: Vec<String> = Vec::new();

    for component in relative_path.split('/') {
        let clean = sanitize_component(component);
        match clean.as_str() {
            "" | "." => continue,
            ".." => {
                current_depth -= 1;
                if current_depth < min_depth {
                    min_depth = current_depth;
                }
                // Never allow depth to go below 0 (stay within sandbox)
                if min_depth < 0 {
                    return Err("Path traversal not permitted".to_string());
                }
                cleaned_components.push("..".to_string());
            }
            _ => {
                current_depth += 1;
                cleaned_components.push(clean);
            }
        }
    }

    // Phase 3: Verify total segment count
    let segment_count = count_path_segments(relative_path);
    if segment_count > max_depth {
        return Err(format!("Path too deep: {} segments (max {})", segment_count, max_depth));
    }

    // Build the validated relative path
    let validated_path: PathBuf = cleaned_components.iter().collect();
    Ok(validated_path)
}

/// Resolves the final absolute path for an upload
fn resolve_upload_path(session: &UploadSession, relative_path: &str) -> Result<PathBuf, String> {
    let validated_relative = validate_path_safety(relative_path, MAX_PATH_DEPTH)?;
    let full_path = session.base_dir.join(&validated_relative);

    // Final canonicalization check - but we need the parent to exist
    // For new files, we check the parent directory
    if let Some(parent) = full_path.parent() {
        if parent.exists() {
            let canonical_parent = parent.canonicalize()
                .map_err(|e| format!("Cannot resolve parent: {}", e))?;
            let upload_root = Path::new(UPLOAD_ROOT).canonicalize()
                .map_err(|e| format!("Cannot resolve upload root: {}", e))?;

            // Check containment
            if !canonical_parent.starts_with(&upload_root) {
                return Err("Resolved path escapes upload root".to_string());
            }
        }
    }

    Ok(full_path)
}

impl UploadSession {
    pub fn new(user_id: String) -> Self {
        let base_dir = PathBuf::from(UPLOAD_ROOT).join(&user_id);
        UploadSession {
            user_id,
            base_dir,
            quota_bytes: 10 * 1024 * 1024, // 10MB
            used_bytes: 0,
        }
    }

    /// Handles a file upload request
    /// The path is user-controlled and specifies where within their directory to store the file
    pub fn upload_file(&mut self, relative_path: &str, content: &[u8]) -> Result<String, String> {
        // Check quota (use checked_add to avoid integer overflow bypassing the check)
        let new_used = self.used_bytes
            .checked_add(content.len() as u64)
            .ok_or_else(|| "Quota exceeded".to_string())?;
        if new_used > self.quota_bytes {
            return Err("Quota exceeded".to_string());
        }

        // Validate and resolve path
        let target_path = resolve_upload_path(self, relative_path)?;

        // Create parent directories if needed
        if let Some(parent) = target_path.parent() {
            fs::create_dir_all(parent)
                .map_err(|e| format!("Cannot create directory: {}", e))?;
        }

        // Write the file
        let mut file = fs::File::create(&target_path)
            .map_err(|e| format!("Cannot create file: {}", e))?;
        file.write_all(content)
            .map_err(|e| format!("Cannot write file: {}", e))?;

        self.used_bytes = self.used_bytes.saturating_add(content.len() as u64);

        Ok(format!("Uploaded to: {}", target_path.display()))
    }

    /// Lists files in a subdirectory
    pub fn list_files(&self, relative_dir: &str) -> Result<Vec<String>, String> {
        let validated_relative = validate_path_safety(relative_dir, MAX_PATH_DEPTH)?;
        let dir_path = self.base_dir.join(&validated_relative);

        if !dir_path.is_dir() {
            return Err("Not a directory".to_string());
        }

        let entries = fs::read_dir(&dir_path)
            .map_err(|e| format!("Cannot read directory: {}", e))?;

        let mut files = Vec::new();
        for entry in entries {
            if let Ok(entry) = entry {
                files.push(entry.file_name().to_string_lossy().to_string());
            }
        }

        Ok(files)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_safe_paths() {
        assert!(validate_path_safety("docs/report.pdf", 8).is_ok());
        assert!(validate_path_safety("a/b/c", 8).is_ok());
    }

    #[test]
    fn test_blocked_traversal() {
        // All traversal attempts should be blocked
        assert!(validate_path_safety("../../etc/passwd", 8).is_err());
        assert!(validate_path_safety("a/../../../etc/passwd", 8).is_err());
        assert!(validate_path_safety("a/../b", 8).is_err());
    }

    #[test]
    fn test_no_relative_allowed() {
        // Even single-level traversal is blocked
        assert!(validate_path_safety("subdir/../other/file.txt", 8).is_err());
    }
}

fn main() {
    let mut session = UploadSession::new("user123".to_string());

    // Normal upload
    match session.upload_file("documents/report.pdf", b"PDF content here") {
        Ok(msg) => println!("Success: {}", msg),
        Err(e) => println!("Error: {}", e),
    }

    // This should be blocked
    match session.upload_file("../../etc/shadow", b"malicious") {
        Ok(msg) => println!("Success: {}", msg),
        Err(e) => println!("Blocked: {}", e),
    }
}
